const alerta = msg.payload;

function formatarData(data) {
    if (!data) return 'Não disponível';

    const dataFormatada = new Date(data);

    if (Number.isNaN(dataFormatada.getTime())) {
        return 'Não disponível';
    }

    return dataFormatada.toLocaleString('pt-PT', {
        timeZone: 'Europe/Lisbon',
        dateStyle: 'short',
        timeStyle: 'medium'
    });
}

function formatarNumero(valor, unidade) {
    if (valor === null || valor === undefined || valor === '') {
        return 'Não disponível';
    }

    return `${Number(valor).toFixed(1)} ${unidade}`;
}

function escaparHTML(valor) {
    return String(valor ?? 'Não disponível')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

const local = alerta.location_name;
const motivo = alerta.risk_reason || alerta.message || 'Risco ALTO identificado';
const avisoIPMA = alerta.ipma_warning_level
    ? alerta.ipma_warning_level
    : 'Sem informação IPMA associada';

msg.alertId = alerta.id;
msg.topic = `ALERTA DE RISCO ALTO - ${local}`;

// Email em texto simples
msg.payload =
`ALERTA DE RISCO COSTEIRO -  ALTO

Local: ${local}
Nível de risco: ALTO
Motivo: ${motivo}

Dados marítimos:
- Data da observação: ${formatarData(alerta.observed_at)}
- Altura das ondas: ${formatarNumero(alerta.wave_height_m, 'm')}
- Período das ondas: ${formatarNumero(alerta.wave_period_s, 's')}

Informação IPMA: ${avisoIPMA}
Fonte dos dados: ${alerta.source || 'Não disponível'}

Alerta criado em: ${formatarData(alerta.created_at)}

Esta mensagem é um alerta automático do projeto de monitorização marítima.`;

// Email em HTML
msg.html = `
<div style="font-family:Arial,sans-serif;max-width:600px;color:#222">
  <h2 style="color:#b00020">ALERTA DE RISCO COSTEIRO - ALTO</h2>

  <p><strong>Local:</strong> ${escaparHTML(local)}</p>
  <p><strong>Motivo:</strong> ${escaparHTML(motivo)}</p>

  <h3>Dados marítimos</h3>
  <ul>
    <li><strong>Data da observação:</strong> ${formatarData(alerta.observed_at)}</li>
    <li><strong>Altura das ondas:</strong> ${formatarNumero(alerta.wave_height_m, 'm')}</li>
    <li><strong>Período das ondas:</strong> ${formatarNumero(alerta.wave_period_s, 's')}</li>
  </ul>

  <h3>Informação complementar</h3>
  <p><strong>Aviso IPMA:</strong> ${escaparHTML(avisoIPMA)}</p>
  <p><strong>Fonte:</strong> ${escaparHTML(alerta.source || 'Não disponível')}</p>
  <p><strong>Alerta criado em:</strong> ${formatarData(alerta.created_at)}</p>

  <hr>
  <p style="font-size:12px;color:#666">
    Mensagem automática do projeto de monitorização marítima.
    Os dados apresentados devem ser interpretados tendo em conta a respetiva fonte.
  </p>
</div>`;

return msg;

msg.params = [msg.alertId];
msg.query = `UPDATE alerts
             SET email_sent = TRUE,
                 email_sent_at = NOW(),
                 last_error = NULL
             WHERE id = $1
               AND email_sent = FALSE
               AND UPPER(TRIM(risk_level)) = 'ALTO'
             RETURNING id, email_sent, email_sent_at;`;
return msg;

const erro = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.params = [msg.alertId, erro.slice(0, 500)];
msg.query  = `UPDATE alerts
              SET email_attempts = email_attempts + 1, last_error = $2
              WHERE id = $1
              RETURNING id, email_attempts, last_error;`;
return msg;

